// Cloudflare Worker entry. The widget's public hot path (session open, claim,
// outcome beacon, design config) is served directly, skipping the Next.js
// request pipeline so it fits the 1.5 s fail-open budget. Everything else is
// handled by the OpenNext build of the full app.
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import nextApp from "./.open-next/worker.js";
import * as claim from "./src/app/api/v1/intercept/claim/route";
import * as init from "./src/app/api/v1/intercept/init/route";
import * as outcome from "./src/app/api/v1/intercept/outcome/route";
import * as widgetConfig from "./src/app/api/v1/widget-config/[publicKey]/route";
import { edgeRequestContext } from "./src/lib/edge/background";

// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

type Ctx = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };
type Handler = (request: Request) => Response | Promise<Response>;

const POST_ROUTES: Record<string, { POST: Handler; OPTIONS: Handler }> = {
  "/api/v1/intercept/init": init,
  "/api/v1/intercept/claim": claim,
  "/api/v1/intercept/outcome": outcome,
};

function lean(request: Request): (() => Response | Promise<Response>) | null {
  const { pathname } = new URL(request.url);
  const route = POST_ROUTES[pathname];
  if (route) {
    if (request.method === "POST") return () => route.POST(request);
    if (request.method === "OPTIONS") return () => route.OPTIONS(request);
    return null;
  }
  const config = /^\/api\/v1\/widget-config\/([^/]+)$/.exec(pathname);
  if (config) {
    if (request.method === "OPTIONS") return () => widgetConfig.OPTIONS();
    if (request.method === "GET") {
      const publicKey = decodeURIComponent(config[1]);
      // Route handlers only use .nextUrl on this request; a plain Request plus nextUrl is enough.
      const nextRequest = Object.assign(request, { nextUrl: new URL(request.url) });
      return () => widgetConfig.GET(nextRequest as never, { params: Promise.resolve({ publicKey }) });
    }
  }
  return null;
}

export default {
  async fetch(request: Request, env: unknown, ctx: Ctx): Promise<Response> {
    const fast = lean(request);
    if (fast) return edgeRequestContext.run(ctx, fast);
    return nextApp.fetch(request, env, ctx);
  },
};
